code.css:
/* Selection widens the row's left inset to make room for the box. */
.row { display: flex; align-items: center; height: 58px; }
.row__checkbox { width: 24px; height: 24px; margin-left: 8px; }

/* Resting the text starts at 8; selecting it starts at 48. */
.row__text { margin-left: 8px; width: 313px; }
.row--selecting .row__text { margin-left: 48px; width: 273px; }

/* The count sits in a pill at the foot, over the list. */
.selection-delete { position: absolute; right: 24px; bottom: 24px; height: 54px; border-radius: 999px; }

code.jsx:
// Select is a mode on the list, not a screen of its own. Three things change:
//
//   every row gains a 24px checkbox and indents its text by 40
//   the bar swaps Search + Select for Select all + Cancel
//   a Delete button appears, counting the memories ticked
//
// The tick is held against the memory id, so a memory drawn in two groups shows
// checked in both and still counts once.

<MemoryRow memory={m} selecting checked={selected.has(m.id)} onToggle={toggle} />

code.swiftui:
// EditMode drives the same three changes.
List(selection: $selected) {
  ForEach(groups) { group in
    Section(group.title) {
      ForEach(group.memories) { MemoryRow(memory: $0) }
    }
  }
}
.environment(\.editMode, .constant(selecting ? .active : .inactive))
.toolbar {
  ToolbarItem(placement: .topBarLeading) { Button("Select all", action: selectAll) }
  ToolbarItem(placement: .topBarTrailing) { Button("Cancel", action: cancel) }
}
